"""CPU-only wide reset for the frozen trained asset; original observation anchor stays exact."""
from pathlib import Path
import os,json,time,hashlib,xml.etree.ElementTree as ET
os.environ['CUDA_VISIBLE_DEVICES']=''
ROOT=Path(__file__).resolve().parents[1]
def sha(p):return hashlib.sha256(Path(p).read_bytes()).hexdigest()
def main():
 import numpy as np,trimesh
 from scipy.optimize import least_squares
 from scipy.spatial.transform import Rotation
 from user_body_kinematics import G1Kinematics
 from user_rohand_coupling import ROHandCoupling
 from hand_geometry import box_signed_distance
 started=time.monotonic();folder=ROOT/'data/robots/g1_box_training';source=folder/'training_asset.json';source_sha=sha(source);assert source_sha=='ce60e669cd519181110ed8c12264636ab601728a8c29a3e538eda1e62b318447';a=json.loads(source.read_text());urdf=folder/'g1_box.urdf';lut=folder/'coupling_lut.npz';assert sha(urdf)==a['urdf_sha256'];assert sha(lut)==a['coupling_lut_sha256'];kin=G1Kinematics(ROOT,scene_path='data/video_generation/candidate_scene/scene_rohand.json');coupling=ROHandCoupling(ROOT);q0=np.asarray(a['reset_body_q']);q=q0.copy();base=np.asarray(a['reset_base_xyz']);quat=np.asarray(a['reset_base_quaternion_xyzw']);open_act=np.asarray(a['open_actuators']);fingers=coupling.expand_one(open_act);offsets=np.asarray(a['palm_local_offsets']);center=np.asarray(a['box_center_xyz_m']);size=np.asarray(a['box_size_xyz_m']);T0=kin.forward(base,quat,q0,fingers);xml=ET.parse(urdf).getroot();geometry=[];source_hashes={}
 for link in xml.findall('link'):
  name=link.attrib['name'];li=kin.link_index[name]
  for collision in link.findall('collision'):
   meshpath=folder/collision.find('geometry/mesh').attrib['filename'];source_hashes[str(meshpath.relative_to(ROOT))]=sha(meshpath);mesh=trimesh.load_mesh(meshpath,process=True);v=np.asarray(mesh.vertices);tri=v[np.asarray(mesh.faces)];samples=np.concatenate([v]+[tri[:,0]*(1-i/4-j/4)+tri[:,1]*(i/4)+tri[:,2]*(j/4)for i in range(5)for j in range(5-i)]);geometry.append({'link':name,'index':li,'vertices':v,'samples':samples})
 assert len(geometry)==57
 # The expanded box is the exact union of all axis-aligned boxes over the
 # whole +/-1cm XY randomization rectangle, stronger than corner-only tests.
 envelope_size=size+np.asarray([.02,.02,0]);envelopeT=np.eye(4);envelopeT[:3,3]=center;ik=[];arm_all=[]
 for si,side in enumerate(('left','right')):
  arm=np.asarray([kin.body_index[side+'_'+s+'_joint']for s in ('shoulder_pitch','shoulder_roll','shoulder_yaw','elbow','wrist_roll','wrist_pitch','wrist_yaw')]);arm_all.extend(arm.tolist());palm=kin.link_index[a['palm_link_names'][si]];goal=T0[palm,:3,:3]@offsets[si]+T0[palm,:3,3];goal[1]=(1 if side=='left'else -1)*(size[1]/2+.060);Rgoal=T0[palm,:3,:3].copy();parts=[g for g in geometry if kin.ancestor[g['index'],arm].any()]
  def decode(x):
   qq=q.copy();qq[arm]=x;T=kin.forward(base,quat,qq,fingers);point=T[palm,:3,:3]@offsets[si]+T[palm,:3,3];rot=Rotation.from_matrix(Rgoal.T@T[palm,:3,:3]).as_rotvec();world=np.concatenate([g['vertices']@T[g['index'],:3,:3].T+T[g['index'],:3,3]for g in parts]);sd=box_signed_distance(world,envelopeT,envelope_size);return T,point,rot,sd
  def residual(x):
   T,p,r,sd=decode(x);pen=np.maximum(.012-sd,0)/.003;return np.r_[(p-goal)/.002,r/.04,pen*np.sqrt(1000/len(pen)),pen.max()*20,(x-q0[arm])*.001]
  fit=least_squares(residual,q[arm],bounds=(kin.body_limits[arm,0],kin.body_limits[arm,1]),max_nfev=180,ftol=1e-11,xtol=1e-11,gtol=1e-10);q[arm]=fit.x;T,p,r,sd=decode(fit.x);row={'side':side,'joint_names':np.asarray(kin.body_joint_names)[arm].tolist(),'target_palm_world_xyz_m':goal.tolist(),'actual_palm_world_xyz_m':p.tolist(),'position_error_m':float(np.linalg.norm(p-goal)),'orientation_error_rad':float(np.linalg.norm(r)),'nfev':fit.nfev,'success':bool(fit.success),'q_delta_rad':(fit.x-q0[arm]).tolist(),'max_abs_delta_rad':float(np.max(np.abs(fit.x-q0[arm])))};ik.append(row);print(json.dumps(row),flush=True)
 Tnew=kin.forward(base,quat,q,fingers);table_center=np.asarray([center[0]+.03,0,a['table_top_z_m']-.02]);table_size=np.asarray([.36,.80,.04]);tableT=np.eye(4);tableT[:3,3]=table_center;cases=[('nominal',center,size)]+[(f'xy_corner_{dx:+.2f}_{dy:+.2f}',center+np.asarray([dx,dy,0]),size)for dx in (-.01,.01)for dy in (-.01,.01)]+[('all_xy_randomization_envelope',center,envelope_size)]
 def certificate(T,c,s):
  bt=np.eye(4);bt[:3,3]=c;rows=[]
  for g in geometry:
   F=T[g['index']];v=g['vertices']@F[:3,:3].T+F[:3,3];p=g['samples']@F[:3,:3].T+F[:3,3];lower=v.min(0);upper=v.max(0);sep=np.maximum(np.maximum(lower-(c+s/2),(c-s/2)-upper),0);cert=float(np.linalg.norm(sep));sd=box_signed_distance(p,bt,s);rows.append({'link':g['link'],'aabb_separation_lower_bound_m':cert,'sampled_surface_min_sdf_m':float(sd.min()),'exact_collision_min_z_m':float(v[:,2].min())})
  return {'minimum_aabb_certified_separation_m':min(x['aabb_separation_lower_bound_m']for x in rows),'minimum_sampled_surface_sdf_m':min(x['sampled_surface_min_sdf_m']for x in rows),'closest_certified_link':min(rows,key=lambda x:x['aabb_separation_lower_bound_m'])['link'],'hulls':rows}
 oldtests={name:certificate(T0,c,s)for name,c,s in cases};newtests={name:certificate(Tnew,c,s)for name,c,s in cases};table_old=certificate(T0,table_center,table_size);table_new=certificate(Tnew,table_center,table_size);feet={name:{'old_min_z_m':min(x['exact_collision_min_z_m']for x in oldtests['nominal']['hulls']if x['link']==name),'new_min_z_m':min(x['exact_collision_min_z_m']for x in newtests['nominal']['hulls']if x['link']==name)}for name in a['foot_link_names']};other=[j for j in range(29)if j not in arm_all];assert np.array_equal(q[other],q0[other]);assert np.all(q>=kin.body_limits[:,0])and np.all(q<=kin.body_limits[:,1]);assert all(x['position_error_m']<.001 and x['orientation_error_rad']<.01 for x in ik);safe=all(x['minimum_aabb_certified_separation_m']>=.010 for x in newtests.values());assert safe,'At least one collider has not certified10mm clearance';assert table_new['minimum_aabb_certified_separation_m']>0;assert all(abs(v['new_min_z_m']-v['old_min_z_m'])<1e-12 for v in feet.values())
 result={'schema':'kinogen.g1_box_reset.2','source_training_asset_path':str(source.relative_to(ROOT)),'source_training_asset_sha256':source_sha,'source_urdf_sha256':sha(urdf),'source_coupling_lut_sha256':sha(lut),'body_joint_names':a['body_joint_names'],'reset_base_xyz':a['reset_base_xyz'],'reset_base_quaternion_xyzw':a['reset_base_quaternion_xyzw'],'reset_body_q':q.tolist(),'pregrasp_body_q':a['reset_body_q'],'observation_body_anchor_q':a['reset_body_q'],'lift_body_q':a['lift_body_q'],'open_actuators':a['open_actuators'],'closed_actuators':a['closed_actuators'],'palm_gap_m':.060,'old_palm_gap_m':.025,'motor_only_approach_duration_s':.5,'motor_only_approach_target_body_q':a['reset_body_q'],'no_active_state_writes':True,'original_phase_schedule_after_approach_preserved':True,'box_xy_randomization_half_range_m':.01,'minimum_required_clearance_m':.010,'whole_randomization_rectangle_certified_safe':safe,'minimum_randomization_envelope_clearance_m':newtests['all_xy_randomization_envelope']['minimum_aabb_certified_separation_m'],'corner_certificates_m':{k:v['minimum_aabb_certified_separation_m']for k,v in newtests.items()},'table_center_xyz_m':table_center.tolist(),'table_size_xyz_m':table_size.tolist(),'table_minimum_certified_clearance_m':table_new['minimum_aabb_certified_separation_m'],'foot_min_z_m':feet,'arm_ik_diagnostics':ik,'changed_joint_names':[kin.body_joint_names[j]for j in range(29)if q[j]!=q0[j]],'all_non_arm_joints_exact':True,'old_training_asset_unchanged':sha(source)==source_sha,'physical_initialization_verified':False,'policy_weights_and_observation_anchor_unchanged':True,'elapsed_seconds':time.monotonic()-started};path=folder/'reset_v2.json';tmp=path.with_suffix('.tmp');tmp.write_text(json.dumps(result,indent=2));tmp.replace(path)
 report={'schema':'kinogen.g1_box_reset_v2.cpu_certificate.1','inputs':{'training_asset':{'path':str(source.relative_to(ROOT)),'sha256':source_sha},'urdf':{'path':str(urdf.relative_to(ROOT)),'sha256':sha(urdf)},'lut':{'path':str(lut.relative_to(ROOT)),'sha256':sha(lut)}},'output':{'path':str(path.relative_to(ROOT)),'sha256':sha(path)},'collision_mesh_sha256':source_hashes,'exact_collider_count':57,'all_non_arm_joints_exact':True,'base_quaternion_exact':True,'source_lift_and_observation_anchor_exact':True,'old_body_q':q0.tolist(),'new_body_q':q.tolist(),'delta_body_q':(q-q0).tolist(),'ik':ik,'old_box_clearance':oldtests,'new_box_clearance':newtests,'old_table_clearance':table_old,'new_table_clearance':table_new,'feet':feet,'certificate_method':'Exact extrema of each frozen convex collider give an enclosing world AABB. AABB-to-axis-aligned-box Euclidean separation is a conservative lower bound for every surface point. Expanded XY box is exact union over entire+-1cm rectangle. Dense surface SDF is additional diagnostic, not the proof.','no_urdf_lut_cad_edits':True,'physical_initialization_verified':False,'elapsed_seconds':time.monotonic()-started};rp=ROOT/'reports/g1-box-reset-v2-cpu.json';rp.write_text(json.dumps(report,indent=2));print(json.dumps({'complete':True,'path':str(path.relative_to(ROOT)),'sha256':sha(path),'report_sha256':sha(rp),'minimum_all_xy_envelope_clearance_m':result['minimum_randomization_envelope_clearance_m'],'table_clearance_m':result['table_minimum_certified_clearance_m'],'feet':feet,'elapsed_seconds':time.monotonic()-started}),flush=True)
if __name__=='__main__':main()
